#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ks(n);
    vector<vector<pair<int,int>>> cells(n);
    int totalCells = 0;
    for(int i = 0; i < n; i++){
        cin >> ks[i];
        cells[i].resize(ks[i]);
        for(int j = 0; j < ks[i]; j++){
            cin >> cells[i][j].first >> cells[i][j].second;
        }
        totalCells += ks[i];
    }

    // Precompute orientations for each piece
    struct OriInfo {
        vector<pair<int,int>> cells; // normalized, sorted
        int w, h;
        int f, r;
    };

    vector<vector<OriInfo>> allOris(n);
    for(int i = 0; i < n; i++){
        set<vector<pair<int,int>>> seen;
        for(int f = 0; f < 2; f++){
            for(int r = 0; r < 4; r++){
                vector<pair<int,int>> tc;
                for(auto [x, y] : cells[i]){
                    int nx = x, ny = y;
                    if(f) nx = -nx;
                    for(int q = 0; q < r; q++){
                        int tmp = nx;
                        nx = ny;
                        ny = -tmp;
                    }
                    tc.push_back({nx, ny});
                }
                int minx = INT_MAX, miny = INT_MAX;
                for(auto [x,y] : tc){ minx = min(minx,x); miny = min(miny,y); }
                for(auto& [x,y] : tc){ x -= minx; y -= miny; }
                sort(tc.begin(), tc.end());
                if(seen.insert(tc).second){
                    int w = 0, h = 0;
                    for(auto [x,y] : tc){ w = max(w, x+1); h = max(h, y+1); }
                    allOris[i].push_back({tc, w, h, f, r});
                }
            }
        }
    }

    // Sort pieces: larger first
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){
        if(ks[a] != ks[b]) return ks[a] > ks[b];
        return a < b;
    });

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now() - startTime).count();
    };

    double sqrtArea = sqrt((double)totalCells * 1.2);

    // Generate candidate widths
    vector<int> candidateW;
    for(double mult = 0.6; mult <= 2.5; mult += 0.05){
        int w = max(10, (int)(sqrtArea * mult));
        candidateW.push_back(w);
    }
    sort(candidateW.begin(), candidateW.end());
    candidateW.erase(unique(candidateW.begin(), candidateW.end()), candidateW.end());

    long long bestArea = (long long)1e18;
    int bestH = INT_MAX, bestW = INT_MAX;

    struct Placement { int x, y, r, f; };
    vector<Placement> bestPlacements(n);
    bool haveSolution = false;

    for(int W : candidateW){
        if(elapsed() > 8.5 && haveSolution) break;

        int maxH = (totalCells + W - 1) / W + totalCells; // generous upper bound
        maxH = min(maxH, totalCells + 100);

        // Use heightmap for fast y-finding
        vector<int> heightmap(W, 0);
        // Use 2D grid for collision detection
        // To save memory, we'll use a flat vector with dynamic height
        int gridH = min(maxH, (int)(totalCells * 3.0 / W + 50));
        vector<vector<bool>> grid(W, vector<bool>(gridH, false));

        vector<Placement> placements(n);
        int curMaxY = 0;
        bool failed = false;

        for(int idx = 0; idx < n && !failed; idx++){
            int pi = order[idx];

            int bestScore = INT_MAX;
            int bx = -1, by = -1, boi = -1;

            for(int oi = 0; oi < (int)allOris[pi].size(); oi++){
                auto& ori = allOris[pi][oi];
                if(ori.w > W) continue;

                for(int x = 0; x <= W - ori.w; x++){
                    // Find min y using heightmap
                    int minY = 0;
                    for(auto [cx, cy] : ori.cells){
                        minY = max(minY, heightmap[x + cx] - cy);
                    }

                    // Check bounds
                    int topY = 0;
                    for(auto [cx, cy] : ori.cells) topY = max(topY, minY + cy + 1);
                    if(topY > gridH){ continue; }

                    // Check no overlap
                    bool ok = true;
                    for(auto [cx, cy] : ori.cells){
                        int py = minY + cy;
                        if(grid[x + cx][py]){ ok = false; break; }
                    }

                    if(ok){
                        int score = topY * 10000 + x;
                        if(score < bestScore){
                            bestScore = score;
                            bx = x; by = minY; boi = oi;
                        }
                    }
                }
            }

            if(bx == -1){ failed = true; break; }

            auto& ori = allOris[pi][boi];
            for(auto [cx, cy] : ori.cells){
                int px = bx + cx, py = by + cy;
                grid[px][py] = true;
                heightmap[px] = max(heightmap[px], py + 1);
                curMaxY = max(curMaxY, py + 1);
            }

            placements[pi] = {bx, by, ori.r, ori.f};
        }

        if(failed) continue;

        int H = curMaxY;
        long long area = (long long)W * H;
        if(area < bestArea || (area == bestArea && (H < bestH || (H == bestH && W < bestW)))){
            bestArea = area;
            bestH = H;
            bestW = W;
            bestPlacements = placements;
            haveSolution = true;
        }
    }

    cout << bestW << " " << bestH << "\n";
    for(int i = 0; i < n; i++){
        cout << bestPlacements[i].x << " " << bestPlacements[i].y << " "
             << bestPlacements[i].r << " " << bestPlacements[i].f << "\n";
    }

    return 0;
}
